from pathlib import Path
from bs4 import BeautifulSoup as Soup
import html,json
R=Path(__file__).resolve().parents[2]
def e(s):return html.escape(s,quote=True)
guides=[
('my-garden','Getting Started With My Garden',['Open the green Open My Garden button beside the Garden Apps introduction on the homepage.','Enter a garden name, growing zone and location, then choose Save Garden Profile.','Start with My Growing Zone, map your space, then use the other tools as your plan develops.','Save inside each tool. Return to My Garden to review the records that tool shares with the dashboard.','Keep using the same browser and device. Export backups where available; this is browser storage, not an online account.']),
('growing-zone','My Growing Zone',['Enter your U.S. ZIP code and run the zone lookup.','Read the USDA hardiness-zone result and its temperature range. Hardiness describes winter survival, not a complete planting calendar.','Save your zone, then open My Garden to review the profile. Cross-check frost dates and local conditions before planting.']),
('garden-planner','Map Garden Space / Garden Planner',['Set the dimensions and units for the area you want to plan.','Add beds, paths and structures, then place crops or search the plant library.','Review mature spread, spacing, light and water context. Adjust the layout to your real site.','Give your layout a name and save it. Reopen the saved plan before changing it, and export a backup when offered.']),
('garden-calculator','Garden Calculator',['Choose the calculation that fits your job, such as soil volume, mulch or plant spacing.','Check the units before entering dimensions. Measure the actual bed rather than estimating from a photograph.','Calculate and review the result. Allow for material settling and the supplier’s package sizes before purchasing.']),
('plant-companions','Plant Companions',['Choose the crop you want to grow and review compatible pairings and cautions.','Use spacing, light, water and rotation needs as the first checks. Companion suggestions are planning guidance, not guaranteed pest control.','Save useful pairings and review them from My Garden when planning a bed.']),
('seasonal-calendar','Seasonal Calendar',['Choose your growing context and browse the month or season.','Read planting, maintenance and harvesting suggestions alongside local frost and weather information.','Use the calendar to plan tasks, then record the work you actually complete in Garden Journal.']),
('plant-identifier','Plant, Pest & Disease Identifier',['Choose the subject you want to investigate and add evidence. Upload or capture the whole plant and useful close-ups.','Provide growing conditions and symptoms. Check that photographs are sharp and well lit.','Review the screening clues and suggested next steps. This tool does not provide definitive laboratory identification or diagnosis.','Save the report for follow-up. Ask a local extension service about uncertain, poisonous, invasive or serious disease cases before acting.']),
('harvest-checker','Harvest Checker',['Choose a crop and provide the variety or maturity context where available.','Compare the crop’s visible readiness signs with the guidance. Harvest timing varies with variety, weather and intended use.','Save your check, then record the actual yield in Harvest & Garden Records.']),
('garden-library','Garden Library',['Use Search the Library to find plant records, terms and reference resources. The silver microphone offers voice search in supported browsers; click again to stop.','Open Plant Records to inspect growing conditions and save useful plants to your library.','Choose 100 Gardening Books to browse the editorial collection. Search by title, author or category.','The first 25 books appear initially. Choose See More to reveal another 25, up to 100.','Open a book guide for its summary, editorial rationale, practical uses, cover credit and Amazon listing. Save private reading notes and export a backup.']),
('seed-starting','Seed Starting & Tray Tracker',['Add the seeds you have, then create a tray or sowing record.','Record sowing dates, cells planted and expected germination or transplant timing.','Update germination and task progress as seedlings develop. Save changes and review tray totals in My Garden.']),
('garden-journal','Garden Journal & Logs',['Create an entry for watering, feeding, soil work, observations or treatment.','Record the date, location or plant, what happened and any follow-up needed.','Save the entry. Review recent activity in My Garden and use the journal to compare results over time.']),
('harvest-records','Harvest & Garden Records',['Add a harvest record with crop, date and quantity. Use consistent units so comparisons make sense.','Add quality, storage and seasonal notes where useful.','Save the record and review totals. Keep Harvest Checker observations separate from measured harvest yields.']),
('garden-inventory','Inventory, Shopping & Budget',['Add seeds, plants, tools or supplies you already own.','Record quantities and low-stock needs, then build a shopping list before buying.','Enter purchases and costs to track actual spending. Save changes and review inventory and budget totals in My Garden.'])]
p=R/'help';p.mkdir(exist_ok=True)
base=Soup((R/'articles/index.html').read_text(),'html.parser')
header=str(base.select_one('.b21StickyBrand'));footer=str(base.footer)
links=''.join(str(x)for x in base.head.select('link[rel=stylesheet]'))+'<link rel="stylesheet" href="/app-assets/app-navigation.css?v=20261021-garden-start">'
scripts=''.join(str(x)for x in base.select('script[src]')if any(n in x.get('src','')for n in ['site-experience','app-navigation','install.js','tanya']))
body='<main class="phg-guide"><p class="kicker">Perennial Garden Guides</p><h1>Help &amp; Tutorials</h1><p>Find your starting point, learn each garden app and turn a plan into something you can grow.</p><section class="guide-intro"><h2>Getting Started With My Garden</h2><p>Start with your garden profile, then explore 12 connected tools. Save your work as you go and return to My Garden for an overview.</p><a class="phg-app-open" href="/tools/my-garden/">Open My Garden →</a><p><a href="#my-garden">Read the getting-started guide ↓</a></p></section><label class="phg-guide-search">Find a guide<input id="guideSearch" type="search" placeholder="Search a tool, task or topic"></label><p id="guideCount" role="status">13 step-by-step guides</p><div id="gardenGuides">'
for slug,title,steps in guides:
 body+='<details id="'+slug+'"'+(' open'if slug=='my-garden'else'')+'><summary>'+e(title)+'</summary><ol>'+''.join('<li>'+e(step)+'</li>'for step in steps)+'</ol><a href="/tools/'+slug+'/">Open '+e(title)+' →</a></details>'
body+='</div><section><h2>Keep your garden records safe</h2><p>Browser storage does not need a membership and does not upload your garden records to our server. It is specific to this browser and device. Clearing browsing data, using private mode or changing devices can make records unavailable. Use each tool’s Save and Export controls where provided.</p></section><p><a href="/#contact">Still need help? Contact Perennial →</a></p></main>'
search='''<script>const search=document.getElementById('guideSearch'),guides=[...document.querySelectorAll('#gardenGuides details')];search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let n=0;for(const g of guides){g.hidden=!g.textContent.toLowerCase().includes(q);if(!g.hidden)n++;}document.getElementById('guideCount').textContent=n+' guides found';});function openHash(){const d=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(d?.tagName==='DETAILS')d.open=true;}window.addEventListener('hashchange',openHash);openHash();</script>'''
if (R/'help/media/getting-started-with-my-garden.mp4').exists():
 video='<video class="phg-guide-video" controls preload="metadata" playsinline aria-label="Getting Started With My Garden tutorial"><source src="/help/media/getting-started-with-my-garden.mp4" type="video/mp4"><track kind="captions" src="/help/media/my-garden-captions.vtt" srclang="en" label="English"></video><p><a href="/help/media/perennial-garden-guide-editing-kit.zip">Download the tutorial editing kit</a></p>'
 body=body.replace('</section><label class="phg-guide-search">',video+'</section><label class="phg-guide-search">',1)
 scripts+='<script src="/app-assets/garden-guide-video.js" defer></script>'
(p/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Help &amp; Tutorials | Perennial Garden Guides</title>'+links+'</head><body>'+header+body+footer+scripts+search+'</body></html>')
(R/'.github/data/garden-help-guides.json').write_text(json.dumps(guides,ensure_ascii=False,indent=2))
print('Built 13 written guides with search and contextual anchors.')
